"""Generate standalone Python from a NexPro syntax tree."""

from inspect import getsource

from nexpro import data_builtins, standard
from nexpro.ast import (
    Member, Module, Slice, Assert, Assign, Binary, Boolean, Call, Function, If, Null, Number, Record, Return, Say, String,
    Unary, Variable, While, Index, ListLiteral, For, Break, Continue, Logical, Dictionary, SetItem, Try, Throw,
)
from nexpro.errors import EXECUTION_ERRORS
_ERROR_TYPES = ", ".join(error.__name__ for error in EXECUTION_ERRORS)


_RUNTIME = """\
# Generated by NexPro
import sys

# NexPro data built-ins
# NexPro standard modules

_source_map = {}
_globals = {}
_functions = {}
_aliases = {}
_module_cache = {}
_builtins = {**DATA_BUILTINS, "len": len, "int": _to_int, "float": float, "input": input, "append": list.append}


def _error_frames(error):
    frames = []
    trace = error.__traceback__
    while trace is not None:
        if trace.tb_frame.f_globals is globals() and trace.tb_lineno in _source_map:
            frames.append(_source_map[trace.tb_lineno])
        trace = trace.tb_next
    return frames


def _caught_record(error):
    frames = _error_frames(error)
    return _error_record(_error_code(error), str(error), frames[-1] if frames else None)


def _get(scope, global_scope, name):
    if name in scope:
        return scope[name]
    if name in global_scope:
        return global_scope[name]
    raise ValueError(f"Undefined variable '{name}'")


def _call(functions, allow_builtin, name, arguments, named):
    if name not in functions:
        if allow_builtin and name in _builtins:
            return _call_builtin(name, _builtins[name], arguments, named)
        raise ValueError(f"Undefined function '{name}'")
    if callable(functions[name]):
        return _call_builtin(name, functions[name], arguments, named)
    parameters, default_count, function = functions[name]
    return function(_argument_scope(name, parameters, default_count, arguments, named))


def _module(aliases, name):
    if name not in aliases:
        raise ValueError(f"Undefined module alias '{name}'")
    return aliases[name]


def _load_module(path, factory):
    if path not in _module_cache:
        _module_cache[path] = factory()
    return _module_cache[path]


def _index(sequence, index):
    return sequence[index]


def _set_item(sequence, index, value):
    sequence[index] = value


if __name__ == '__main__':
    _configure_stdio()
    try:
"""


class GeneratedCode(list):
    def __init__(self):
        runtime = _RUNTIME.replace("# NexPro data built-ins", getsource(data_builtins).rstrip())
        runtime = runtime.replace("# NexPro standard modules", getsource(standard).rstrip())
        super().__init__(runtime.splitlines())
        self.locations = {}
        self.function = "<program>"

    def emit(self, line, node):
        self.append(line)
        if node.location is not None:
            self.locations[len(self)] = (self.function, *node.location)

    def set_source_map(self):
        line = self.index("_source_map = {}")
        self[line] = f"_source_map = {self.locations!r}"


def _expression(node, lines, indent):
    if isinstance(node, Null):
        return "None"
    if isinstance(node, (String, Number, Boolean)):
        # Python exposes infinity through float() and has no literal for it.
        if isinstance(node, Number) and node.value == float("inf"):
            return "float('inf')"
        return repr(node.value)
    if isinstance(node, Logical):
        left = _expression(node.left, lines, indent)
        temporary = f"_value_{len(lines)}"
        lines.emit(f"{indent}{temporary} = bool({left})", node)
        test = temporary if node.operator == "and" else f"not {temporary}"
        lines.append(f"{indent}if {test}:")
        inner = indent + "    "
        right = _expression(node.right, lines, inner)
        lines.emit(f"{inner}{temporary} = bool({right})", node)
        return temporary
    if isinstance(node, Dictionary):
        temporary = f"_value_{len(lines)}"
        lines.append(f"{indent}{temporary} = {{}}")
        for key, value in node.entries:
            index = _expression(key, lines, indent)
            item = _expression(value, lines, indent)
            lines.emit(f"{indent}{temporary}[{index}] = {item}", node)
        return temporary
    if isinstance(node, Variable):
        value = f"_get(_scope, _globals, {node.name!r})"
    elif isinstance(node, Member):
        value = f"_get({{}}, _module(_aliases, {node.namespace!r})[0], {node.name!r})"
    elif isinstance(node, Binary):
        left = _expression(node.left, lines, indent)
        right = _expression(node.right, lines, indent)
        if node.operator in ("//", "%", "**"):
            value = f"_extended_arithmetic({node.operator!r}, {left}, {right})"
        else:
            value = f"{left} {node.operator} {right}"
    elif isinstance(node, Unary):
        operand = _expression(node.operand, lines, indent)
        operator = "not " if node.operator == "not" else node.operator
        value = f"{operator}{operand}"
    elif isinstance(node, ListLiteral):
        elements = [_expression(element, lines, indent) for element in node.elements]
        value = f"[{', '.join(elements)}]"
    elif isinstance(node, Slice):
        parts = [_expression(item, lines, indent) if item is not None else "None"
                 for item in (node.start, node.stop, node.step)]
        value = f"slice({', '.join(parts)})"
    elif isinstance(node, Index):
        sequence = _expression(node.sequence, lines, indent)
        index = _expression(node.index, lines, indent)
        value = f"_index({sequence}, {index})"
    elif isinstance(node, Call):
        arguments = [_expression(argument, lines, indent) for argument in node.arguments]
        target = "_functions, True" if node.namespace is None else f"_module(_aliases, {node.namespace!r})[1], False"
        named = [f"{name!r}: {_expression(argument, lines, indent)}" for name, argument in node.named_arguments]
        value = f"_call({target}, {node.name!r}, [{', '.join(arguments)}], {{{', '.join(named)}}})"
    else:
        raise TypeError(f"Unsupported expression {type(node).__name__}")

    # Separate operations avoid Python's nesting limit for long source expressions.
    temporary = f"_value_{len(lines)}"
    lines.emit(f"{indent}{temporary} = {value}", node)
    return temporary


def _statements(statements, lines, indent):
    if not statements:
        lines.append(f"{indent}pass")
    for statement in statements:
        if isinstance(statement, Module):
            path = statement.path
            target = (
                f"({{}}, STANDARD_MODULES[{path!r}])" if path in standard.STANDARD_MODULES
                else f"_load_module({path!r}, {lines.modules[path]})"
            )
            lines.emit(f"{indent}_aliases[{statement.alias!r}] = {target}", statement)
        elif isinstance(statement, Assign):
            value = _expression(statement.value, lines, indent)
            lines.append(f"{indent}_scope[{statement.variable.name!r}] = {value}")
        elif isinstance(statement, SetItem):
            sequence = _expression(statement.target.sequence, lines, indent)
            index = _expression(statement.target.index, lines, indent)
            value = _expression(statement.value, lines, indent)
            lines.emit(f"{indent}_set_item({sequence}, {index}, {value})", statement)
        elif isinstance(statement, Say):
            value = _expression(statement.expression, lines, indent)
            lines.emit(f"{indent}_say_value({value})", statement)
        elif isinstance(statement, Call):
            _expression(statement, lines, indent)
        elif isinstance(statement, Assert):
            value = _expression(statement.condition, lines, indent)
            lines.append(f"{indent}if not {value}:")
            lines.emit(f"{indent}    raise ValueError('Assertion failed')", statement)
        elif isinstance(statement, Return):
            value = _expression(statement.value, lines, indent)
            lines.append(f"{indent}return {value}")
        elif isinstance(statement, If):
            condition = _expression(statement.condition, lines, indent)
            lines.emit(f"{indent}if {condition}:", statement)
            _statements(statement.then_body, lines, indent + "    ")
            if statement.else_body is not None:
                lines.append(f"{indent}else:")
                _statements(statement.else_body, lines, indent + "    ")
        elif isinstance(statement, Try):
            lines.append(f"{indent}try:")
            inner = indent + "    "
            _statements(statement.body, lines, inner)
            lines.append(f"{indent}except ({_ERROR_TYPES}) as _caught:")
            value = "_caught_record(_caught)" if statement.structured else "str(_caught)"
            lines.append(f"{inner}_scope[{statement.error_name!r}] = {value}")
            _statements(statement.handler, lines, inner)
        elif isinstance(statement, Throw):
            code = _expression(statement.code, lines, indent) if statement.code is not None else "'thrown'"
            value = _expression(statement.message, lines, indent)
            lines.emit(f"{indent}_throw({value}, {code})", statement)
        elif isinstance(statement, While):
            lines.append(f"{indent}while True:")
            body_indent = indent + "    "
            condition = _expression(statement.condition, lines, body_indent)
            lines.emit(f"{body_indent}if not {condition}:", statement)
            lines.append(f"{body_indent}    break")
            _statements(statement.body, lines, body_indent)
        elif isinstance(statement, For):
            iterable = _expression(statement.iterable, lines, indent)
            item = f"_item_{len(lines)}"
            lines.emit(f"{indent}for {item} in {iterable}:", statement)
            body_indent = indent + "    "
            lines.append(f"{body_indent}_scope[{statement.name!r}] = {item}")
            _statements(statement.body, lines, body_indent)
        elif isinstance(statement, Break):
            lines.append(f"{indent}break")
        elif isinstance(statement, Continue):
            lines.append(f"{indent}continue")
        elif isinstance(statement, Function):
            name = f"_function_{len(lines)}"
            lines.append(f"{indent}def {name}(_scope):")
            outer = lines.function
            lines.function = statement.name
            body_indent = indent + "    "
            optional_parameters = statement.parameters[len(statement.parameters) - len(statement.defaults):]
            for parameter, default in zip(optional_parameters, statement.defaults):
                lines.append(f"{body_indent}if {parameter!r} not in _scope:")
                value = _expression(default, lines, body_indent + "    ")
                lines.emit(f"{body_indent}    _scope[{parameter!r}] = {value}", statement)
            if isinstance(statement, Record):
                lines.emit(f"{body_indent}return _Record({statement.name!r}, {tuple(statement.parameters)!r}, _scope)", statement)
            else:
                _statements(statement.body, lines, body_indent)
                lines.append(f"{body_indent}return None")
            lines.function = outer
            lines.append(
                f"{indent}_functions[{statement.name!r}] = "
                f"({tuple(statement.parameters)!r}, {len(statement.defaults)}, {name})"
            )
        else:
            raise TypeError(f"Unsupported statement {type(statement).__name__}")


def compile_program(program):
    """Return Python source for a parsed NexPro program."""
    lines = GeneratedCode()
    modules = getattr(program, "modules", {})
    lines.modules = {path: f"_module_{i}" for i, path in enumerate(modules)}
    for path, body in modules.items():
        lines.append(f"        def {lines.modules[path]}():")
        lines.append("            _scope = _globals = {}")
        lines.append("            _functions = {}")
        lines.append("            _aliases = {}")
        _statements(body, lines, "            ")
        lines.append("            return _globals, _functions")
    lines.append("        _scope = _globals")
    _statements(program.statements, lines, "        ")
    lines.extend([
        f"    except ({_ERROR_TYPES}) as error:",
        "        print(f'NexPro Runtime Error: {error}', file=sys.stderr)",
        "        for function, filename, line in reversed(_error_frames(error)):",
        "            print(f'  at {function} ({filename}:{line})', file=sys.stderr)",
        "        sys.exit(1)",
    ])
    lines.set_source_map()
    return "\n".join(lines) + "\n"
